(()=>{const A=Abibi;A.$('#branches-list').innerHTML=A.D.branches.map(b=>`<button type="button" class="branch-choice" data-branch="${b.id}"><span class="branch-symbol">⌂</span><span class="flex-grow-1"><strong>${b.name}</strong><small>${b.type}</small><small>⌖ ${b.area}</small></span><span>←</span></button>`).join('');document.addEventListener('click',e=>{const b=e.target.closest('[data-branch]');if(!b)return;const bid=Number(b.dataset.branch);if(A.state.branch&&bid!==A.state.branch&&A.count()&&!confirm('با تغییر شعبه سبد خرید فعلی پاک می‌شود. ادامه می‌دهی؟'))return;if(bid!==A.state.branch)A.state.cart=[];A.state.branch=bid;A.save();const next=sessionStorage.getItem('abibi-return');sessionStorage.removeItem('abibi-return');location.href=next&&/^(menu|home|product|cart|checkout|favorites)\.html(\?[^#]*)?$/.test(next)?next:'home.html'})})();
